struct Ref:H8SEmulator{void history(){lastread=lastwrite=-1;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc100&&a<0xc300)||(a>=0xac3a&&a<0xacba);}
struct RBus:H8SDevice{Ref&c;std::array<Event,8>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,8>e{};unsigned n=0;bool enabled=false;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc!=2)return 77;bool boot=false;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc100,0x200);c->memmap(&x,0xac3a,0x80);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerMainUiKeyRuntime rt;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!rt.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;for(unsigned a:{0x3f66u,0x4054u,0x3eb4u,0x3edeu,0x3dc4u,0x3e36u,0x3e74u,0x3c48u,0x3c80u,0x3d4eu,0x3d82u,0x3e26u,0x3cb8u}){c->memory[a]=0x54;c->memory[a+1]=0x70;}uint64_t graphs=0,phases=0,events=0,shorts=0;for(unsigned scenario=0;scenario<32;++scenario)for(unsigned flags=0;flags<256;++flags){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};for(unsigned i=0;i<0x200;++i)put(0xc100+i,uint8_t(i*31+flags));uint8_t key=scenario<11?uint8_t(0x10+scenario):scenario<21?uint8_t(scenario-11):uint8_t(0x30+scenario);uint16_t head=scenario%8?2:0,tail=0;put(0xc144,0);put(0xc145,head);put(0xc146,0);put(0xc147,tail);put(0xc148,flags&1?0:1);put(0xc149,key);uint32_t entry=0x3c10;c->pc=c->makepc(entry);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=((flags&0x81)==0x81)?1:0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history();d->lastRead=d->lastWrite=-1;if(!rt.start())return 3;for(unsigned k=0;rt.active();++k){if(k>1000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto q=rt.request();if(q.service!=kstation::ControllerMainUiKeyRuntime::Service::None){using S=kstation::ControllerMainUiKeyRuntime::Service;if(q.service==S::UnsupportedHandler||at!=(q.target&0xffffff)||(q.key!=uint8_t(c->reg8(14))||q.state!=uint8_t(c->reg8(6)))){std::fprintf(stderr,"request pc=%x target=%x key=%x/%x\n",at,q.target,q.key,uint8_t(c->reg8(14)));return 20;}auto before=c->cycles;c->step();d->cycles+=c->cycles-before;d->lastRead=-1;if(!rt.completeService(q.service))return 21;continue;}auto cost=rt.nextClocks(*d,irq);if(!cost){std::fprintf(stderr,"cost pc=%x scenario=%u flags=%u\n",at,scenario,flags);return 5;}if(phases%31==0){auto before=d->cycles;for(unsigned b=0;b<cost;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}}c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x scenario=%u flags=%u clocks=%llu/%llu io=%u/%u\n",at,scenario,flags,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x scenario=%u addr=%x/%x value=%x/%x time=%llu/%llu\n",at,scenario,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;if(std::memcmp(c->memory+0xc100,d->memory+0xc100,0x200))return 12;++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
